export const sectorSlugByPurpose: Record<string, string> = Object.fromEntries(
  sectors.map((s) => [s.purpose, s.slug])
);

export function getSector(slug: string): Sector | null {
  return sectors.find((s) => s.slug === slug) ?? null;
}
